from typing import Dict, Any, List

class FeedbackEngine:
    """
    Converts technique observations and biomechanical measurements into clear coaching advice.
    Enforces explainable AI rules, non-diagnostic disclaimers, and evidence-backed statements.
    """
    
    DISCLAIMER = (
        "AI Coaching Note: This analysis is generated by automated computer-vision biomechanical algorithms "
        "for academic/training guidance only. It does not constitute medical advice or physical diagnosis."
    )

    @staticmethod
    def generate_feedback(observations: List[Dict[str, Any]], shot_type: str) -> List[Dict[str, Any]]:
        feedbacks = []

        for obs in observations:
            cat = obs["category"]
            sev = obs["severity"]
            val = obs.get("metric_value", 0.0)
            metric_name = obs.get("metric_name", "")

            # Formulate explainable coaching advice
            if metric_name == "head_instability_score":
                msg = (
                    f"Head stability indicator measured at {val:.1f} (reference limit: 3.5). "
                    "Focus on keeping your head STILL and eyes level through ball impact to maintain balance."
                )
            elif metric_name == "min_knee_flex_angle":
                msg = (
                    f"Front knee flexion measured at {val:.1f}°. "
                    "Flexing the front knee over the foot line provides a solid foundation and smoother weight transfer."
                )
            elif metric_name == "avg_trunk_inclination":
                msg = (
                    f"Trunk inclination averaged {val:.1f}° from vertical. "
                    "Ensure your spine posture stays balanced over your base of support without falling backward or forward."
                )
            elif metric_name == "max_elbow_extension":
                msg = (
                    f"Front elbow extension reached {val:.1f}°. "
                    "Leading with a high front elbow assists in keeping the bat face presented straight toward the bowler."
                )
            else:
                msg = obs["observation"]

            feedbacks.append({
                "category": cat,
                "severity": sev,
                "message": msg,
                "confidence": obs["confidence"]
            })

        return feedbacks
